import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";

// The practice set that ships with the app (generated by handbook-mfg/ais/set2_tpl.py). These are the rules the database importer (ais_set_import) and the
// template engine (ais__resolve_vars, ais__subst) enforce, plus the one the engine silently ignores: a variable in a field NAME is never substituted.
type Tpl = { title: string; date: string; docs: { type: string; fields: Record<string, string> }[]; vars: Record<string, unknown>[] };
type Tx = { seq: number; template: Tpl; key: { decision: string; failed_control?: string; explanation: string; journal?: { acct: string; dr?: string | number; cr?: string | number }[] } };
const set: { id: string; title: string; meta: { documents: number; valid: number; exceptions: number; population: { customers: string[]; approval_limit: number } }; txns: Tx[] } =
  JSON.parse(readFileSync(new URL("../src/lib/aisSets/pinagpala-expenditure-feb-2027.json", import.meta.url), "utf8"));

// the control tags in ais_controls after migrations 0075 to 0087
const TAGS = new Set(["CREDIT_LIMIT", "CUTOFF", "DUP_INVOICE", "MATH_ERROR", "NO_AUTHORIZATION", "NO_CREDIT_MEMO", "NO_RECEIVING_REPORT", "NO_SHIPPING_NOTICE", "PRICE_MISMATCH", "QTY_MISMATCH", "SOD", "UNAPPROVED_VENDOR",
  "GHOST_EMPLOYEE", "TERMINATED_PAID", "IMPLAUSIBLE_HOURS", "UNAUTH_OVERTIME", "UNAUTH_RATE", "CAPEX_ERROR"]);
const strings = (x: unknown, out: string[] = []): string[] => {
  if (typeof x === "string") out.push(x);
  else if (Array.isArray(x)) x.forEach((v) => strings(v, out));
  else if (x && typeof x === "object") Object.values(x).forEach((v) => strings(v, out));
  return out;
};

test("the set has an id, a title and distinct sequence numbers", () => {
  assert.ok(set.id && set.title);
  assert.equal(set.txns.length, set.meta.documents);
  assert.equal(new Set(set.txns.map((t) => t.seq)).size, set.txns.length);
});

test("every key is valid for the importer: POST has a journal of two or more lines, HOLD names a known control", () => {
  let posts = 0;
  for (const t of set.txns) {
    assert.ok(["POST", "HOLD"].includes(t.key.decision), `seq ${t.seq}`);
    if (t.key.decision === "POST") { posts++; assert.ok((t.key.journal?.length ?? 0) >= 2, `seq ${t.seq} journal`); }
    else assert.ok(TAGS.has(t.key.failed_control ?? ""), `seq ${t.seq} tag ${t.key.failed_control}`);
  }
  assert.equal(posts, set.meta.valid);
  assert.equal(set.txns.length - posts, set.meta.exceptions);
});

test("no variable sits in a field name or a document type, and every {{variable}} is defined by the template", () => {
  for (const t of set.txns) {
    const names = new Set(t.template.vars.map((v) => String(v.name)));
    assert.equal(names.size, t.template.vars.length, `seq ${t.seq}: duplicate variable name`);
    for (const d of t.template.docs) {
      assert.ok(!d.type.includes("{{"), `seq ${t.seq}: variable in a document type`);
      for (const k of Object.keys(d.fields)) assert.ok(!k.includes("{{"), `seq ${t.seq}: variable in the field name "${k}"`);
    }
    const used = strings([t.template.title, t.template.docs.map((d) => Object.values(d.fields)), t.key.explanation]);
    for (const s of used) for (const m of s.matchAll(/\{\{([A-Za-z0-9_.]+)\}\}/g)) assert.ok(names.has(m[1].split(".")[0]), `seq ${t.seq}: {{${m[1]}}} is not defined`);
    for (const l of t.key.journal ?? []) for (const v of [l.dr, l.cr]) if (typeof v === "string") assert.ok(names.has(v), `seq ${t.seq}: journal uses undefined ${v}`);
  }
});

test("the audit population takes its customer names and the 50,000 limit from the set", () => {
  assert.ok(set.meta.population.customers.length >= 5);
  assert.equal(set.meta.population.approval_limit, 50000);
});
